{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "乱桌现状",
      "setting": "工位，桌面堆满水杯、快递盒、散落便签",
      "mood": "真实、不评判"
    },
    {
      "scene_id": "S2",
      "name": "四步整理",
      "setting": "同一张桌子的近景与俯拍，分屏加计时器",
      "mood": "清晰、可执行"
    },
    {
      "scene_id": "S3",
      "name": "干净桌面收尾",
      "setting": "俯拍整洁桌面，留出一掌空白区域",
      "mood": "轻松、有余地"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "近景平推：镜头贴着桌面滑过水杯、快递盒和散落便签，最终停在屏幕旁的 3 分钟计时便签上。",
      "duration_sec": 5,
      "camera": "手持近景平移"
    },
    {
      "shot_id": "SH02",
      "scene": "S1",
      "description": "中景固定：人物坐在桌前，抬手把视线正前方的杂物往两侧推开，画面右上角计时器开始 3:00。",
      "duration_sec": 8,
      "camera": "中景固定机位"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "俯拍特写：手里只抽出一张纸写下今天三件事，其余便签收进抽屉，动作连贯不剪辑。",
      "duration_sec": 9,
      "camera": "垂直俯拍特写"
    },
    {
      "shot_id": "SH04",
      "scene": "S2",
      "description": "分屏三段：笔进笔筒、线绕好入盒、充电线从头理到尾，三格同步完成。",
      "duration_sec": 10,
      "camera": "三分屏特写"
    },
    {
      "shot_id": "SH05",
      "scene": "S2",
      "description": "俯拍中景：手在桌面正中空出一掌大的空白区域，手指轻点该区域作为提示。",
      "duration_sec": 6,
      "camera": "俯拍中景"
    },
    {
      "shot_id": "SH06",
      "scene": "S3",
      "description": "俯拍全景：计时器停在 2:41，干净桌面完整入画，随后叠出结尾文字板“明天开工前，先做这四步”。",
      "duration_sec": 7,
      "camera": "俯拍全景缓慢后拉"
    }
  ]
}
